def main():
    _build_dataset()

    dataset = {
        "version": "1.0.0",
        "description": "BSL Code Search Evaluation Dataset - Phase 58",
        "total_queries": len(queries),
        "categories": {
            "functionality_search": "Search for business functionality by description",
            "api_search": "Search for platform API usage patterns",
            "business_logic": "Search for business process implementations",
            "pattern_search": "Search for BSL coding patterns and idioms",
        },
        "queries": queries,
    }

    os.makedirs(OUT_DIR, exist_ok=True)
    out_path = os.path.join(OUT_DIR, "bsl_eval_dataset.json")

    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(dataset, f, ensure_ascii=False, indent=2)

    print(f"Written {len(queries)} queries to {out_path}")
    for cat in ["functionality_search", "api_search", "business_logic", "pattern_search"]:
        count = sum(1 for q in queries if q["category"] == cat)
        print(f"  {cat}: {count}")


if __name__ == "__main__":
    main()
